// Extract message data
const message = $input.first().json;

return {
  json: {
    user_id: message.user_id,
    message_type: message.type,
    text: message.text || '',
    media_url: message.media_url || null,
    session_id: message.session_id || null,
    client_id: message.client_id || null
  }
};

// Merge classification and emotion results
const intent = $input.all()[0].json;
const emotion = $input.all()[1].json;

// Determine route
let chain = 'conversational';
const intentClass = intent.intent_class;
const stressLevel = emotion.stress_level;

if (intentClass === 'research_request' || intentClass === 'deep_analysis') {
  chain = 'research';
} else if (intentClass === 'action_required' || intentClass === 'multi_step_task') {
  chain = 'react_agent';
} else if (intentClass === 'pattern_query' || intentClass === 'data_analysis') {
  chain = 'analysis';
} else if (stressLevel === 'high' || intentClass === 'distress') {
  chain = 'empathy';
}

return {
  json: {
    user_id: $input.first().json.user_id,
    text: $input.first().json.text,
    message_type: $input.first().json.message_type,
    session_id: $input.first().json.session_id,
    intent_class: intentClass,
    emotion_scores: emotion.scores,
    stress_level: stressLevel,
    target_chain: chain
  }
};

// Apply personality compilation
const response = $input.first().json;
const context = response.context || {};

// Determine personality mode
let mode = 'sharp';
const stress = context.emotional?.stress_level;
const period = context.temporal?.period;

if (stress === 'high') {
  mode = 'empathic';
} else if (period === 'morning') {
  mode = 'energetic';
} else if (period === 'evening') {
  mode = 'warm';
}

return {
  json: {
    ...response,
    personality_mode: mode,
    response_text: response.content,
    tillu_message: response.content  // Personality-applied
  }
};
